var GSI_SRC="https://accounts.google.com/gsi/client";function initGoogleSignIn(){var wrap=document.getElementById("google-signin-wrap");if(!wrap)return;var clientId=typeof APP_CONFIG!=="undefined"&&APP_CONFIG.GOOGLE_CLIENT_ID||"";if(!clientId)return;loadGsiScript(function(loaded){if(!loaded||!window.google||!google.accounts||!google.accounts.id)return;try{google.accounts.id.initialize({client_id:clientId,callback:onGoogleCredential,auto_select:false,cancel_on_tap_outside:true});google.accounts.id.renderButton(document.getElementById("google-signin-btn"),{theme:"outline",size:"large",width:280,text:"continue_with",shape:"rectangular"});wrap.hidden=false}catch(e){}})}function loadGsiScript(done){if(window.google&&window.google.accounts&&window.google.accounts.id)return done(true);var existing=document.querySelector('script[src="'+GSI_SRC+'"]');if(existing){existing.addEventListener("load",function(){done(true)});existing.addEventListener("error",function(){done(false)});return}var s=document.createElement("script");s.src=GSI_SRC;s.async=true;s.defer=true;s.onload=function(){done(true)};s.onerror=function(){done(false)};document.head.appendChild(s)}async function onGoogleCredential(response){var errorEl=document.getElementById("google-signin-error");var wrap=document.getElementById("google-signin-wrap");if(errorEl)errorEl.textContent="";if(!response||!response.credential){if(errorEl)errorEl.textContent="Google sign-in did not complete. Please try again.";return}if(wrap)wrap.classList.add("is-busy");var res=await Api.post("googleSignIn",{credential:response.credential,sharedDevice:typeof sharedDeviceChecked==="function"?sharedDeviceChecked():false});if(wrap)wrap.classList.remove("is-busy");if(!res.ok){if(errorEl)errorEl.textContent=res.error||"Could not sign you in with Google.";return}CustomerAuth.saveSession(res.token,res.customer);window.location.href=typeof nextDest==="function"?nextDest():"customer-dashboard.html"}document.addEventListener("DOMContentLoaded",initGoogleSignIn);